package com.example.smartpantry.ui;

import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import com.example.smartpantry.data.PantryDbHelper;import com.example.smartpantry.model.Models.PantryItem;

public class AddEditIngredientActivity extends Activity { PantryDbHelper db; PantryItem editing; EditText name,qty,unit,expiry; Button save,del;
 public void onCreate(Bundle b){super.onCreate(b);db=new PantryDbHelper(this);long id=getIntent().getLongExtra("id",0);if(id>0)for(PantryItem x:db.getPantry())if(x.id==id)editing=x;build();}
 EditText field(String hint){EditText e=new EditText(this);e.setHint(hint);e.setTextSize(16);e.setSingleLine(true);e.setPadding(24,8,24,8);return e;}
 void build(){LinearLayout p=Ui.page(this);p.addView(Ui.title(this,editing==null?"Add ingredient":"Edit ingredient"));p.addView(Ui.label(this,"Ingredient name *"));name=field("e.g. tomatoes");p.addView(name,new LinearLayout.LayoutParams(-1,58));p.addView(Ui.label(this,"Quantity *"));qty=field("e.g. 2");qty.setInputType(2|8192);p.addView(qty,new LinearLayout.LayoutParams(-1,58));p.addView(Ui.label(this,"Unit *"));unit=field("g, ml, count, tbsp...");p.addView(unit,new LinearLayout.LayoutParams(-1,58));p.addView(Ui.label(this,"Expiry date (optional)"));expiry=field("YYYY-MM-DD");p.addView(expiry,new LinearLayout.LayoutParams(-1,58));save=Ui.button(this,editing==null?"Save ingredient":"Save changes");LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,58);sp.setMargins(24,24,24,8);p.addView(save,sp);save.setOnClickListener(v->save());if(editing!=null){del=Ui.button(this,"Delete ingredient");p.addView(del,sp);del.setOnClickListener(v->{db.deletePantry(editing.id);finish();});name.setText(editing.name);qty.setText(String.valueOf(editing.quantity));unit.setText(editing.unit);expiry.setText(editing.expiry);}Button back=Ui.button(this,"Cancel");p.addView(back,sp);back.setOnClickListener(v->finish());setContentView(p);}
 void save(){String n=name.getText().toString().trim(),u=unit.getText().toString().trim();if(n.isEmpty()||u.isEmpty()){Toast.makeText(this,"Name and unit are required",Toast.LENGTH_SHORT).show();return;}double q;try{q=Double.parseDouble(qty.getText().toString().trim());}catch(Exception e){Toast.makeText(this,"Enter a valid quantity",Toast.LENGTH_SHORT).show();return;}if(q<=0){Toast.makeText(this,"Quantity must be greater than zero",Toast.LENGTH_SHORT).show();return;}PantryItem x=editing==null?new PantryItem():editing;x.name=n;x.quantity=q;x.unit=u;x.expiry=expiry.getText().toString().trim();db.savePantry(x);finish();}
}
